-- =======================================================================
-- SCRIPT DE ACTUALIZACIÓN DE BECAS (SUPABASE)
-- =======================================================================

-- 1. MANTENER SOLO 1 BECA (LA MÁS ANTIGUA) Y BORRAR EL RESTO
DELETE FROM public.becas 
WHERE id NOT IN (
    SELECT id FROM public.becas ORDER BY id LIMIT 1
);

-- 2. INSERTAR NUEVAS BECAS (REALES)
ON CONFLICT (id) DO UPDATE SET titulo = EXCLUDED.titulo, sponsor = EXCLUDED.sponsor, cobertura = EXCLUDED.cobertura, requisitos = EXCLUDED.requisitos, fecha_cierre = EXCLUDED.fecha_cierre, nivel = EXCLUDED.nivel, icono = EXCLUDED.icono, sobre = EXCLUDED.sobre, beneficios = EXCLUDED.beneficios, afinidad = EXCLUDED.afinidad, url_oficial = EXCLUDED.url_oficial;
